const api_url=document.querySelector('meta[name="random-api-url"]').content;async function fetch_random(t){const i=new AbortController,n=setTimeout(()=>i.abort(),4e4);try{const a=await fetch(api_url+t,{signal:i.signal}),e=await a.json();if(!a.ok)throw new Error(e.error_message||"\u4E71\u6570\u751F\u6210\u306B\u5931\u6557\u3057\u307E\u3057\u305F\u3002");return e}finally{clearTimeout(n)}}function update_output(t){const i=document.getElementById("id_output");i.value="";for(let n=0;n<t.length;n++)i.value+=t[n]+`
`}function send_and_get(t,i){const n=document.getElementById("id_output");n.value="\u4E71\u6570\u3092\u751F\u6210\u4E2D..";const a=new URLSearchParams(i).toString(),e=`/${t}?${a}`;fetch_random(e).then(m=>{m.rand_array?update_output(m.rand_array):m.error_message&&alert(m.error_message)}).catch(m=>{n.value="",alert(`\u4E71\u6570\u751F\u6210API\u306B\u30A2\u30AF\u30BB\u30B9\u3067\u304D\u307E\u305B\u3093\u3002
\u3057\u3070\u3089\u304F\u5F85\u3063\u3066\u304B\u3089\u518D\u5EA6\u304A\u8A66\u3057\u304F\u3060\u3055\u3044\u3002

${m}`)})}function uniform(){const t=document.getElementById("id_trials"),i=document.getElementById("id_integer_mode"),n=document.getElementsByName("range_uniform"),a=document.getElementById("id_input_min_uniform"),e=document.getElementById("id_input_max_uniform"),m=document.getElementById("id_input_digit_uniform"),l={};if(i.checked?l.type="int":l.type="float",l.trials=t.value,n[0].checked)l.max=parseInt(e.value),l.min=parseInt(a.value);else if(n[1].checked){let o=parseInt(m.value),u=Math.pow(10,o-1),d=Math.pow(10,o)-1;l.max=d,l.min=u}send_and_get("uniform",l)}function normal(){const t=document.getElementById("id_trials"),i=document.getElementById("id_integer_mode"),n=document.getElementById("id_input_mu"),a=document.getElementById("id_input_sigma"),e={};i.checked?e.type="int":e.type="float",e.trials=t.value,e.mu=n.value,e.sigma=a.value,send_and_get("normal",e)}function beta(){const t=document.getElementById("id_trials"),i=document.getElementById("id_integer_mode"),n=document.getElementById("id_input_alpha"),a=document.getElementById("id_input_beta"),e={};i.checked?e.type="int":e.type="float",e.trials=t.value,e.alpha=n.value,e.beta=a.value,send_and_get("beta",e)}function triangular(){const t=document.getElementById("id_trials"),i=document.getElementById("id_integer_mode"),n=document.getElementsByName("range_triangular"),a=document.getElementById("id_input_min_triangular"),e=document.getElementById("id_input_max_triangular"),m=document.getElementById("id_input_digit_triangular"),l=document.getElementById("id_input_mode"),o={};if(i.checked?o.type="int":o.type="float",o.trials=t.value,n[0].checked)o.max=parseInt(e.value),o.min=parseInt(a.value);else if(n[1].checked){let u=parseInt(m.value),d=Math.pow(10,u-1),c=Math.pow(10,u)-1;o.max=c,o.min=d}o.mode=l.value,send_and_get("triangular",o)}function lambda(){const t=document.getElementById("id_trials"),i=document.getElementById("id_integer_mode"),n=document.getElementById("id_input_lambda"),a={};i.checked?a.type="int":a.type="float",a.trials=t.value,a.lambda=n.value,send_and_get("lambda",a)}function gamma(){const t=document.getElementById("id_trials"),i=document.getElementById("id_integer_mode"),n=document.getElementById("id_input_gamma_alpha"),a=document.getElementById("id_input_gamma_beta"),e={};i.checked?e.type="int":e.type="float",e.trials=t.value,e.alpha=n.value,e.beta=a.value,send_and_get("gamma",e)}function OnMakeButtonClick(){const t=document.getElementById("id_select_random");t.value=="uniform"?uniform():t.value=="normal"?normal():t.value=="beta"?beta():t.value=="triangular"?triangular():t.value=="lambda"?lambda():t.value=="gamma"&&gamma()}$(window).on("load",function(){information_show_if_needed("yapps_info_random_250420","information_button")});
